const COURSE = [
  /* ---------------- 1. Getting started ---------------- */
  ['start', 'intro', ['مقدمة: ماذا ستتعلم؟', 'Introduction: what you will learn'],
    ['أهلاً بك! في هذه الدورة ستتعلم ClickUp خطوة بخطوة، من أول حساب حتى إدارة فريق كامل بمساعدة الذكاء الاصطناعي. سنبني معاً خطة مشروع حقيقية، ثم نعرضها بطرق مختلفة، ونتواصل مع الفريق، ونقيس التقدم، ونترك الأتمتة تتولى الأعمال المتكررة.', 'Welcome! In this course you learn ClickUp step by step, from your very first account to running a whole team with help from AI. Together we build a real project plan, look at it in different views, talk with the team, measure progress, and let automations handle the repetitive work.'],
    [['اقرأ شرح كل موضوع ثم طبّق الخطوات في ClickUp أو في مختبر التطبيق.', 'Read each topic, then follow the steps in ClickUp or in the Practice Lab.'], ['علّم الموضوع «تم» عند الانتهاء لتتابع تقدمك.', 'Mark the topic as done when you finish to track your progress.'], ['اسأل كليكي تشات بوت إن احتجت شرحاً إضافياً.', 'Ask Clicky Chatbot when you need more explanation.']],
    ['لا تحاول حفظ كل شيء دفعة واحدة. موضوع واحد في اليوم مع تطبيق بسيط يكفي لتصبح محترفاً خلال أسابيع.', 'Do not try to memorise everything at once. One topic a day with a small practice is enough to become a pro within weeks.'], '#/tour'],
  ['start', 'account', ['إعداد حسابك', 'Setting up your account'],
    ['الحساب هو بطاقة دخولك إلى ClickUp. في العمل تدخل غالباً ببريد الشركة أو بالدخول الموحّد (SSO)، ثم تنضم إلى مساحة عمل الشركة بدعوة من المسؤول. خمس دقائق في ضبط الصورة والاسم والمنطقة الزمنية توفر عليك ارتباكاً كثيراً لاحقاً.', 'Your account is your pass into ClickUp. At work you usually sign in with your company email or single sign-on (SSO), then join the company Workspace through an admin’s invite. Five minutes spent on your photo, name and time zone saves a lot of confusion later.'],
    [['افتح app.clickup.com أو التطبيق وسجّل الدخول ببريد العمل.', 'Open app.clickup.com or the app and sign in with your work email.'], ['اقبل دعوة مساحة العمل إن وصلتك.', 'Accept the Workspace invite if you received one.'], ['من صورتك ← Settings أضف صورة واضحة واختر توقيت مسقط (GMT+4).', 'From your avatar, open Settings, add a clear photo and choose the Muscat time zone (GMT+4).']],
    ['الصورة الحقيقية تجعل زملاءك يعرفونك بسرعة في التعليقات والمهام المسندة.', 'A real photo helps colleagues recognise you quickly in comments and assigned tasks.'], 'l1-1'],
  ['start', 'interface', ['الواجهة: أين كل شيء؟', 'The interface: where everything lives'],
    ['واجهة ClickUp مثل مبنى مرتّب: الشريط الجانبي هو المصعد الذي يأخذك إلى المساحات والقوائم، والجزء الأوسط هو الغرفة التي تعمل فيها، والشريط العلوي فيه البحث والإنشاء السريع. في الإصدار 4.0 يوجد شريط تنقل عام يضم الصفحة الرئيسية وصندوق الوارد والمستندات والمحادثات والذكاء الاصطناعي.', 'The ClickUp interface is like a tidy building: the sidebar is the lift that takes you to Spaces and Lists, the middle is the room where you work, and the top bar holds search and quick create. In version 4.0 a global navigation bar groups Home, Inbox, Docs, Chat and AI.'],
    [['جرّب فتح مساحة وقائمة من الشريط الجانبي.', 'Open a Space and a List from the sidebar.'], ['اضغط Ctrl/Cmd+K وابحث عن أي مهمة.', 'Press Ctrl/Cmd+K and search for any task.'], ['ثبّت ما تستخدمه كثيراً في المفضلة (Favorites).', 'Pin what you use often to Favorites.']],
    ['إن ضعت في الواجهة، فاضغط Ctrl/Cmd+K؛ البحث يوصلك لأي مكان أسرع من التنقل.', 'If you get lost, press Ctrl/Cmd+K; search gets you anywhere faster than clicking around.'], 'l1-2'],

  /* ---------------- 2. Building the project plan ---------------- */
  ['build', 'hierarchy', ['هيكل ClickUp: مساحة العمل، المساحة، المجلد، القائمة، المهمة', 'The ClickUp structure: Workspace, Space, Folder, List, Task'],
    ['تخيّل ClickUp كخزانة ملفات. مساحة العمل (Workspace) هي الشركة كلها. المساحة (Space) درج لقسم أو فريق. المجلد (Folder) ملف لمشروع. القائمة (List) ورقة تضم المهام. والمهمة (Task) هي العمل الفعلي الذي ينجزه شخص. فهم هذا الترتيب هو أهم خطوة لتعرف أين تضع كل شيء.', 'Think of ClickUp as a filing cabinet. The Workspace is the whole company. A Space is a drawer for a department or team. A Folder is a file for a project. A List is a sheet that holds tasks. A Task is the actual work someone does. Understanding this order is the most important step to know where everything goes.'],
    [['ارسم مشروعك على ورقة: من القسم؟ ما المشروع؟ ما المراحل؟', 'Sketch your project on paper: which department, which project, which stages?'], ['اجعل القسم مساحة، والمشروع مجلداً، وكل مرحلة قائمة.', 'Make the department a Space, the project a Folder, and each stage a List.'], ['ضع المهام داخل القوائم فقط.', 'Put tasks inside Lists only.']],
    ['المجلد اختياري. إن كان المشروع صغيراً فقائمة واحدة داخل المساحة تكفي.', 'Folders are optional. For a small project, a single List inside the Space is enough.'], 'l2-1'],
  ['build', 'structure1', ['إنشاء هيكل المشروع (الجزء 1): المساحة والمجلد', 'Creating the project structure, part 1: Space and Folder'],
    ['لنبنِ مشروعاً تدريبياً اسمه «إطلاق خدمة الألياف في صلالة». نبدأ بالحاوية الكبيرة: مساحة للفريق ثم مجلد للمشروع. هكذا يبقى كل ما يخص المشروع في مكان واحد ويسهل إيجاده.', 'Let’s build a practice project called “Fibre service launch in Salalah”. We start with the big container: a Space for the team, then a Folder for the project. That way everything about the project stays in one place and is easy to find.'],
    [['في الشريط الجانبي اضغط «+» بجانب المساحات وأنشئ مساحة باسم الفريق.', 'In the sidebar click “+” next to Spaces and create a Space with your team’s name.'], ['اختر لوناً وأيقونة، وحدد من يدخلها.', 'Pick a colour and icon, and choose who can access it.'], ['داخل المساحة أنشئ مجلداً باسم المشروع.', 'Inside the Space create a Folder with the project name.']],
    ['استخدم أسماء واضحة يفهمها أي زميل جديد، وتجنب الاختصارات الغامضة.', 'Use clear names any new colleague would understand, and avoid cryptic abbreviations.'], 'l2-2'],
  ['build', 'structure2', ['إنشاء هيكل المشروع (الجزء 2): القوائم والحالات', 'Creating the project structure, part 2: Lists and statuses'],
    ['الآن نقسم المشروع إلى قوائم، كل قائمة مرحلة: «التخطيط»، «التنفيذ»، «الإطلاق». ثم نضبط الحالات (Statuses) التي تمر بها المهمة مثل «للتنفيذ» ← «قيد العمل» ← «مراجعة» ← «مكتمل». الحالات هي خريطة الطريق التي ترى منها أين يقف العمل.', 'Now we split the project into Lists, one per stage: “Planning”, “Delivery”, “Launch”. Then we set the Statuses a task moves through, such as To do → In progress → Review → Complete. Statuses are the road map that shows where the work stands.'],
    [['داخل المجلد أنشئ قائمة لكل مرحلة.', 'Inside the Folder create one List per stage.'], ['من إعدادات المجلد أو القائمة افتح Statuses وأضف حالة «مراجعة».', 'From the Folder or List settings open Statuses and add a “Review” status.'], ['احفظ مجموعة الحالات كقالب لتستخدمها في مشاريع أخرى.', 'Save the status set as a template to reuse in other projects.']],
    ['قلّل الحالات قدر الإمكان. أربع أو خمس حالات تكفي لمعظم الفرق.', 'Keep statuses few. Four or five are enough for most teams.'], 'l2-2'],
  ['build', 'subtasks', ['إنشاء المهام الفرعية', 'Creating subtasks'],
    ['المهمة الكبيرة تُخيف، والمهام الفرعية (Subtasks) تقسمها إلى قطع صغيرة يمكن إنجازها. لكل مهمة فرعية مسؤول وموعد وحالة خاصة بها، فيعرف كل شخص جزءه بالضبط. أما الخطوات الصغيرة التي ينجزها الشخص نفسه فاستخدم لها قائمة تحقق (Checklist).', 'A big task feels scary; subtasks split it into small pieces you can finish. Each subtask has its own assignee, date and status, so everyone knows exactly their part. For small steps the same person does, use a Checklist instead.'],
    [['افتح المهمة واضغط «Add subtask».', 'Open the task and click “Add subtask”.'], ['اكتب اسم كل جزء واضغط Enter.', 'Type the name of each part and press Enter.'], ['أسند كل مهمة فرعية إلى شخص وحدد موعدها.', 'Assign each subtask to a person and give it a date.']],
    ['قاعدة سهلة: إذا عمل عليها شخص آخر فهي مهمة فرعية، وإن كانت خطوة لك وحدك فهي بند في قائمة تحقق.', 'Easy rule: if someone else works on it, it is a subtask; if it is a step for you alone, it is a checklist item.'], 'l3-3'],
  ['build', 'invite', ['دعوة أعضاء الفريق وإسناد المهام', 'Inviting and assigning team members'],
    ['المشروع لا ينجح بشخص واحد. يدعو المسؤول الزملاء إلى مساحة العمل، ثم تشارك المساحة أو القائمة معهم وتسند لكل منهم مهامه. الإسناد يجعل الجواب عن سؤال «من سيفعل هذا؟» واضحاً للجميع.', 'A project does not succeed with one person. An admin invites colleagues to the Workspace, then you share the Space or List with them and assign each one their tasks. Assigning makes the answer to “who is doing this?” clear to everyone.'],
    [['اطلب من المسؤول دعوة الزميل، أو ادعه من People إن كانت لديك الصلاحية.', 'Ask an admin to invite the colleague, or invite them from People if you have permission.'], ['شارك القائمة معه من زر Share.', 'Share the List with them from the Share button.'], ['في المهمة اضغط على Assignee واختر اسمه.', 'In the task click Assignee and pick their name.']],
    ['مسؤول واحد لكل مهمة أفضل. أضف الباقين متابعين (Watchers) ليصلهم التحديث دون التباس.', 'One assignee per task works best. Add others as watchers so they get updates without confusion.'], 'l3-2'],
  ['build', 'dates', ['ضبط تواريخ الاستحقاق', 'Setting up due dates'],
    ['المهمة بلا موعد مجرد أمنية. تاريخ البدء يقول متى يبدأ العمل، وتاريخ الاستحقاق يقول متى يجب أن ينتهي. التواريخ تغذي التقويم وغانت وتذكيرات «مهامي»، فتصبح الخطة حيّة.', 'A task with no date is just a wish. The start date says when work begins and the due date says when it must be finished. Dates feed the Calendar, Gantt and the reminders in My Tasks, so the plan comes alive.'],
    [['في المهمة اضغط على أيقونة التاريخ.', 'In the task click the date icon.'], ['اختر تاريخ البدء ثم تاريخ الاستحقاق، وأضف وقتاً إن احتجت.', 'Choose a start date, then a due date, and add a time if needed.'], ['للمهام الدورية فعّل التكرار (Recurring) من نفس النافذة.', 'For routine tasks turn on Recurring in the same window.']],
    ['ضع مواعيد واقعية. موعد يتأخر دائماً يُفقد الفريق الثقة في الخطة.', 'Set realistic dates. A date that always slips makes the team lose trust in the plan.'], 'l3-2'],
  ['build', 'columns', ['إضافة أعمدة إضافية', 'Adding extra columns'],
    ['في عرض القائمة تظهر المهام كجدول مرتب، ويمكنك إضافة أعمدة لما يهمك: الأولوية، تاريخ البدء، الوقت المقدّر، أو حقل خاص بكم. الأعمدة تجعلك ترى صورة المشروع كاملة دون فتح كل مهمة.', 'In List view tasks appear as a tidy table, and you can add columns for what matters to you: priority, start date, time estimate, or a field of your own. Columns let you see the whole project without opening every task.'],
    [['في نهاية رؤوس الأعمدة اضغط «+».', 'At the end of the column headers click “+”.'], ['اختر عموداً جاهزاً أو أنشئ حقلاً مخصصاً.', 'Pick a ready column or create a Custom Field.'], ['اسحب الأعمدة لترتيبها كما تحب.', 'Drag the columns to arrange them how you like.']],
    ['لا تملأ الشاشة بالأعمدة. أبقِ ما تحتاجه يومياً وأخفِ الباقي.', 'Do not flood the screen with columns. Keep what you need daily and hide the rest.'], 'l4-1'],
  ['build', 'grouping', ['تجميع المهام', 'Grouping tasks'],
    ['التجميع (Group by) يرتب المهام في مجموعات، مثل مجموعة لكل حالة أو لكل مسؤول أو لكل أولوية. فجأة ترى من عنده عمل كثير، وما المهام العاجلة.', 'Grouping sorts tasks into groups, such as one group per status, per assignee or per priority. Suddenly you can see who has a lot of work and which tasks are urgent.'],
    [['في أعلى العرض اضغط «Group».', 'At the top of the view click “Group”.'], ['اختر المسؤول أو الأولوية أو الحالة.', 'Choose assignee, priority or status.'], ['احفظ العرض ليبقى التجميع للفريق.', 'Save the view so the grouping stays for the team.']],
    ['التجميع حسب المسؤول ممتاز لاجتماع المتابعة الأسبوعي.', 'Grouping by assignee is perfect for the weekly follow-up meeting.'], 'l4-3'],
  ['build', 'filter', ['التصفية والبحث', 'Filtering and searching'],
    ['كلما كبر المشروع زادت المهام. التصفية (Filter) تخفي ما لا يهمك الآن، مثل «مهامي العاجلة هذا الأسبوع». والبحث يجد أي مهمة أو مستند بكلمة واحدة.', 'The bigger the project, the more tasks. Filters hide what does not matter right now, like “my urgent tasks this week”. Search finds any task or Doc with a single word.'],
    [['اضغط Filter وأضف شرطاً: المسؤول = أنا.', 'Click Filter and add a rule: Assignee = me.'], ['أضف شرطاً ثانياً: الأولوية = عاجل.', 'Add a second rule: Priority = Urgent.'], ['للبحث في كل مكان اضغط Ctrl/Cmd+K.', 'To search everywhere press Ctrl/Cmd+K.']],
    ['زر «Me» في أعلى العرض يريك مهامك فقط بنقرة واحدة.', 'The “Me” button at the top of a view shows only your tasks in one click.'], 'l4-3'],
  ['build', 'bulk', ['الإجراءات الجماعية على المهام', 'Bulk actions on tasks'],
    ['تخيل أنك تريد نقل 20 مهمة إلى زميل آخر. بدلاً من فتحها واحدة واحدة، حدد المهام كلها وغيّرها مرة واحدة: المسؤول، الحالة، التاريخ، النقل أو الحذف. توفير وقت حقيقي!', 'Imagine moving 20 tasks to another colleague. Instead of opening them one by one, select them all and change them at once: assignee, status, date, move or delete. Real time saved!'],
    [['في عرض القائمة حدد المربعات بجانب المهام.', 'In List view tick the boxes next to the tasks.'], ['يظهر شريط الإجراءات في الأسفل.', 'The action bar appears at the bottom.'], ['اختر الإجراء، مثل تغيير المسؤول، وأكّد.', 'Pick the action, such as changing the assignee, and confirm.']],
    ['راجع التحديد قبل الحذف الجماعي؛ المحذوف يبقى في سلة المهملات نحو 30 يوماً فقط.', 'Check your selection before a bulk delete; deleted items stay in Trash for only about 30 days.'], 'l3-5'],
  ['build', 'finalize', ['اللمسات الأخيرة على عرض خطة المشروع', 'Finalising the project plan view'],
    ['الآن نرتب العرض ليصبح لوحة قيادة المشروع: الأعمدة المهمة ظاهرة، المهام مجمعة حسب المرحلة، ومرتبة حسب التاريخ. ثم نحفظ العرض ليفتحه الجميع بنفس الشكل.', 'Now we tidy the view into the project’s cockpit: the important columns visible, tasks grouped by stage, sorted by date. Then we save the view so everyone opens it the same way.'],
    [['رتب المهام حسب تاريخ الاستحقاق (Sort).', 'Sort the tasks by due date.'], ['أخفِ الأعمدة غير المهمة.', 'Hide columns you do not need.'], ['اضغط Save view، أو اجعله العرض الافتراضي.', 'Click Save view, or make it the default view.']],
    ['سمِّ العرض باسم يشرح هدفه، مثل «خطة المشروع – حسب المرحلة».', 'Name the view after its purpose, such as “Project plan – by stage”.'], 'l4-3'],
  ['build', 'customfields', ['الحقول المخصصة', 'Custom Fields'],
    ['الحقول المخصصة (Custom Fields) تضيف معلومات خاصة بعملك لكل مهمة، مثل المنطقة، رقم الطلب، أو التكلفة. أنواعها كثيرة: نص، رقم، مبلغ، قائمة منسدلة، تاريخ، مربع اختيار، ومعادلة. وهي ما يجعل التقارير والتصفية دقيقة.', 'Custom Fields add information specific to your work to every task, such as region, request number or cost. There are many types: text, number, money, dropdown, date, checkbox and formula. They are what makes reports and filters precise.'],
    [['أضف عموداً جديداً واختر نوع الحقل.', 'Add a new column and choose the field type.'], ['للخيارات الثابتة استخدم Dropdown، مثل «مسقط، صلالة، صحار».', 'For fixed choices use a Dropdown, such as “Muscat, Salalah, Sohar”.'], ['املأ الحقل في المهام، ثم جرّب التصفية به.', 'Fill the field in tasks, then try filtering by it.']],
    ['القائمة المنسدلة أفضل من النص الحر؛ تمنع الأخطاء الإملائية وتجعل التقارير صحيحة.', 'A dropdown beats free text; it prevents typos and keeps reports accurate.'], 'l5-1'],
  ['build', 'changes', ['تعديلات اللحظة الأخيرة على الخطة', 'Last-minute changes to the plan'],
    ['الخطط تتغير دائماً: موعد يتأخر، شخص يغيب، أو مرحلة تُضاف. الجميل في ClickUp أن التعديل سهل: اسحب التاريخ، أعد الإسناد، أو انقل المهام، وسجل النشاط يحفظ كل تغيير ليعرف الجميع ما حدث.', 'Plans always change: a date slips, someone is away, or a stage is added. The nice thing in ClickUp is that changes are easy: drag the date, reassign, or move tasks, and the Activity log keeps every change so everyone knows what happened.'],
    [['غيّر التاريخ بالسحب في التقويم أو غانت.', 'Change dates by dragging in Calendar or Gantt.'], ['أعد إسناد مهام الزميل الغائب بإجراء جماعي.', 'Reassign the absent colleague’s tasks with a bulk action.'], ['اكتب تعليقاً يشرح سبب التغيير.', 'Write a comment explaining why it changed.']],
    ['بعد أي تغيير كبير، أخبر الفريق في تعليق أو قناة المشروع؛ لا تعتمد على أن يلاحظوا وحدهم.', 'After any big change, tell the team in a comment or the project channel; do not count on them noticing.'], 'l7-2'],

  /* ---------------- 3. Views ---------------- */
  ['views', 'list', ['عرض القائمة', 'The List view'],
    ['عرض القائمة (List) هو الأساس: جدول بسيط بالمهام وأعمدتها. مناسب للتخطيط وكتابة المهام بسرعة ومراجعة التفاصيل. تذكّر: كل العروض تُظهر نفس المهام، الذي يتغير فقط هو الشكل.', 'List view is the foundation: a simple table of tasks and their columns. It is great for planning, writing tasks quickly and checking details. Remember: every view shows the same tasks; only the shape changes.'],
    [['افتح أي قائمة؛ عرض List غالباً هو الافتراضي.', 'Open any List; List view is usually the default.'], ['اضغط «+ Task» لإضافة مهمة.', 'Click “+ Task” to add a task.'], ['جرب التجميع والتصفية من الأعلى.', 'Try grouping and filters from the top.']],
    ['عرض القائمة هو الأسرع لإضافة عشر مهام متتالية: اكتب واضغط Enter وكرر.', 'List view is the fastest way to add ten tasks in a row: type, press Enter, repeat.'], 'l4-1'],
  ['views', 'board', ['عرض اللوحة (Board)', 'The Board view'],
    ['عرض اللوحة يحوّل المهام إلى بطاقات في أعمدة حسب الحالة، مثل لوحة الملاحظات اللاصقة. تسحب البطاقة من «قيد العمل» إلى «مكتمل» فتتغير حالتها. ممتاز لرؤية أين يتكدس العمل.', 'Board view turns tasks into cards in columns by status, like a sticky-note wall. Drag a card from In progress to Complete and its status changes. Excellent for seeing where work piles up.'],
    [['اضغط «+ View» واختر Board.', 'Click “+ View” and choose Board.'], ['اسحب بطاقة إلى عمود آخر.', 'Drag a card to another column.'], ['جرب التجميع حسب المسؤول بدلاً من الحالة.', 'Try grouping by assignee instead of status.']],
    ['إذا امتلأ عمود «مراجعة» دائماً فهذا يعني أن المراجعة هي عنق الزجاجة.', 'If the Review column is always full, review is your bottleneck.'], 'l4-1'],
  ['views', 'calendar', ['عرض التقويم', 'The Calendar view'],
    ['التقويم يضع المهام على أيام الشهر أو الأسبوع حسب تواريخها. ترى بنظرة الأيام المزدحمة والأيام الفارغة، ويمكنك سحب المهمة إلى يوم آخر لتغيير موعدها.', 'Calendar places tasks on the days of the month or week by their dates. At a glance you see busy days and free days, and you can drag a task to another day to change its date.'],
    [['أضف عرض Calendar.', 'Add a Calendar view.'], ['بدّل بين اليوم والأسبوع والشهر.', 'Switch between day, week and month.'], ['اسحب مهمة إلى يوم جديد.', 'Drag a task to a new day.']],
    ['المهام بلا تاريخ تظهر في قائمة جانبية؛ اسحبها إلى التقويم لجدولتها.', 'Tasks without dates sit in a side list; drag them onto the calendar to schedule them.'], 'l4-2'],
  ['views', 'gantt', ['عرض غانت', 'The Gantt view'],
    ['غانت يرسم كل مهمة كشريط على خط زمني من تاريخ البدء إلى الاستحقاق. ويُظهر الاعتماديات كخطوط بين المهام: «هذه تنتظر تلك». مثالي لمديري المشاريع لرؤية تأثير أي تأخير.', 'Gantt draws each task as a bar on a timeline from start to due date. It shows dependencies as lines between tasks: “this waits for that”. Ideal for project managers to see the impact of any delay.'],
    [['أضف عرض Gantt.', 'Add a Gantt view.'], ['اسحب طرفي الشريط لتغيير التواريخ.', 'Drag the ends of a bar to change dates.'], ['اسحب من نقطة شريط إلى آخر لإنشاء اعتمادية.', 'Drag from one bar’s dot to another to create a dependency.']],
    ['ابحث عن «المسار الحرج» في غانت: سلسلة المهام التي إن تأخرت تأخر المشروع كله.', 'Look for the critical path in Gantt: the chain of tasks that delays the whole project if it slips.'], 'l4-2'],
  ['views', 'table', ['عرض الجدول', 'The Table view'],
    ['عرض الجدول يشبه جدول بيانات Excel: خلايا تعدّلها مباشرة ويمكنك نسخها ولصقها. مناسب لتعديل بيانات كثيرة بسرعة أو تجهيزها للتصدير.', 'Table view feels like an Excel sheet: cells you edit directly and can copy and paste. It is good for editing a lot of data quickly or preparing it for export.'],
    [['أضف عرض Table.', 'Add a Table view.'], ['انقر خلية وعدّلها مباشرة.', 'Click a cell and edit it directly.'], ['جرّب نسخ عمود من Excel ولصقه.', 'Try copying a column from Excel and pasting it.']],
    ['عرض الجدول مكان ممتاز لتنظيف البيانات قبل التقارير.', 'Table view is a great place to clean data before reporting.'], 'l4-2'],
  ['views', 'whiteboard', ['عرض السبورة (Whiteboard)', 'The Whiteboard view'],
    ['السبورة مساحة رسم مشتركة للعصف الذهني: ملاحظات لاصقة، أشكال، أسهم وصور. والميزة الرائعة أنك تحوّل أي ملاحظة إلى مهمة حقيقية بنقرة، فالأفكار لا تضيع.', 'A Whiteboard is a shared canvas for brainstorming: sticky notes, shapes, arrows and images. The great part is you can turn any note into a real task with a click, so ideas are never lost.'],
    [['أضف Whiteboard من «+ View» أو من زر Create.', 'Add a Whiteboard from “+ View” or the Create button.'], ['ضع ملاحظات لاصقة للأفكار.', 'Drop sticky notes for ideas.'], ['حدد ملاحظة واختر تحويلها إلى مهمة.', 'Select a note and choose to convert it to a task.']],
    ['ابدأ اجتماع التخطيط بالسبورة، وأنهه بتحويل الأفكار المتفق عليها إلى مهام.', 'Start the planning meeting on a Whiteboard and end it by turning the agreed ideas into tasks.'], 'l6-2'],
  ['views', 'timeline', ['عرض الخط الزمني (Timeline)', 'The Timeline view'],
    ['الخط الزمني يشبه غانت لكنه أبسط ومرتب حسب الأشخاص أو المجموعات. يجيب بسرعة عن سؤال: من يعمل على ماذا ومتى؟', 'Timeline is similar to Gantt but simpler and arranged by people or groups. It quickly answers: who is working on what, and when?'],
    [['أضف عرض Timeline.', 'Add a Timeline view.'], ['اختر التجميع حسب المسؤول.', 'Choose to group by assignee.'], ['اسحب المهام لتعديل الفترات.', 'Drag tasks to adjust periods.']],
    ['استخدم Timeline لعرض خطة الفريق على المدير، وGantt للتفاصيل الدقيقة.', 'Use Timeline to show the team plan to your manager, and Gantt for the fine detail.'], 'l4-2'],
  ['views', 'workload', ['عرض الفريق وعبء العمل', 'Team and Workload views'],
    ['عرض عبء العمل (Workload) يقارن عمل كل شخص بقدرته في كل يوم، فترى من مشغول أكثر من اللازم ومن لديه وقت. وعرض الفريق يعرض مهام كل عضو تحت اسمه. معاً يساعدانك على توزيع العمل بعدل.', 'The Workload view compares each person’s work with their capacity each day, so you see who is overloaded and who has time. The Team view shows each member’s tasks under their name. Together they help you share work fairly.'],
    [['أضف عرض Workload.', 'Add a Workload view.'], ['اختر طريقة القياس: عدد المهام أو الوقت المقدر.', 'Choose how to measure: task count or time estimates.'], ['اسحب مهمة من شخص مشغول إلى شخص لديه وقت.', 'Drag a task from a busy person to someone with time.']],
    ['ضع تقديرات الوقت للمهام ليصبح عرض عبء العمل دقيقاً.', 'Add time estimates to tasks so the Workload view is accurate.'], 'l4-2'],
  ['views', 'activity', ['عرض النشاط', 'The Activity view'],
    ['عرض النشاط يعرض كل ما يحدث في القائمة أو المساحة كأخبار متتالية: من أنشأ مهمة، من غيّر حالة، من علّق. ممتاز لمعرفة ما فاتك بعد إجازة.', 'The Activity view shows everything happening in a List or Space as a news feed: who created a task, who changed a status, who commented. Great for catching up after a holiday.'],
    [['أضف عرض Activity إن كان متاحاً في إصدارك.', 'Add an Activity view if your version offers it.'], ['صفِّ حسب الشخص أو نوع التغيير.', 'Filter by person or type of change.'], ['انقر أي حدث لفتح المهمة.', 'Click any event to open the task.']],
    ['لسجل مهمة واحدة، افتح المهمة وانظر إلى Activity بجانب التعليقات.', 'For the history of one task, open it and look at Activity next to the comments.'], 'l3-4'],
  ['views', 'docsforms', ['المستندات وعرض النموذج', 'Docs and Form views'],
    ['المستند (Doc) مكان كتابة الأدلة والمحاضر والسياسات داخل المشروع، ويمكن ربط المهام فيه. وعرض النموذج (Form) يجمع الطلبات من الآخرين: كل نموذج يُرسل يصبح مهمة في القائمة تلقائياً.', 'A Doc is where you write guides, minutes and procedures inside the project, and you can link tasks in it. The Form view collects requests from others: every submitted form becomes a task in the List automatically.'],
    [['أضف Doc من «+ View» واكتب دليل المشروع.', 'Add a Doc from “+ View” and write the project guide.'], ['أضف Form واسحب الحقول المطلوبة.', 'Add a Form and drag in the fields you need.'], ['شارك رابط النموذج وجرب إرساله.', 'Share the form link and try submitting it.']],
    ['اجعل الأسئلة المهمة في النموذج إلزامية حتى تصل الطلبات كاملة.', 'Make important form questions required so requests arrive complete.'], 'l10-1'],
  ['views', 'mindmap', ['لوحات المعلومات والخرائط الذهنية وعرض الخريطة', 'Dashboards, Mind Maps and Map view'],
    ['ثلاث طرق للنظر من بعيد: لوحة المعلومات تجمع الأرقام والرسوم، والخريطة الذهنية (Mind Map) ترسم المهام والأفكار كشجرة متفرعة، وعرض الخريطة (Map) يضع المهام على خريطة جغرافية حسب حقل الموقع، مثلاً مواقع الأبراج أو الفروع.', 'Three ways to look from a distance: a Dashboard gathers numbers and charts, a Mind Map draws tasks and ideas as a branching tree, and the Map view places tasks on a geographic map by a Location field, for example tower or branch sites.'],
    [['جرّب Mind Map لتقسيم هدف كبير إلى فروع.', 'Try a Mind Map to break a big goal into branches.'], ['أضف حقل Location ثم عرض Map.', 'Add a Location field, then a Map view.'], ['سنتعمق في لوحات المعلومات في قسمها الخاص.', 'We go deeper into Dashboards in their own section.']],
    ['عرض الخريطة مفيد جداً للفرق الميدانية: ترى أي المواقع لديها مهام مفتوحة.', 'The Map view is very useful for field teams: you see which sites have open tasks.'], 'l8-1'],

  /* ---------------- 4. AI ---------------- */
  ['ai', 'brain', ['مقدمة إلى ClickUp Brain', 'Intro to ClickUp Brain AI'],
    ['ClickUp Brain هو الذكاء الاصطناعي المدمج في ClickUp. ميزته أنه يعرف سياق عملك: يقرأ المهام والمستندات التي لديك صلاحية رؤيتها، فيلخص ويكتب ويجيب ويقترح. توفر ميزاته يعتمد على خطة الاشتراك وما فعّله مسؤولو مساحة العمل.', 'ClickUp Brain is the AI built into ClickUp. Its strength is that it knows the context of your work: it reads the tasks and Docs you are allowed to see, so it can summarise, write, answer and suggest. Which features you get depends on your plan and on what your Workspace admins turned on.'],
    [['ابحث عن زر AI أو أيقونة Brain في الشريط أو داخل المهمة.', 'Look for the AI button or Brain icon in the bar or inside a task.'], ['اطلب تلخيص مهمة طويلة.', 'Ask it to summarise a long task.'], ['راجع الناتج دائماً قبل الاعتماد عليه.', 'Always review the output before relying on it.']],
    ['لا تُدخل بيانات سرية أو بيانات عملاء ما لم تسمح بذلك سياسة الشركة المعتمدة.', 'Do not enter confidential or customer data unless an approved company policy allows it.'], '#/workshops/ai'],
  ['ai', 'knowledge', ['مدير المعرفة بالذكاء الاصطناعي', 'ClickUp AI Knowledge Manager'],
    ['مدير المعرفة (Knowledge Manager) هو جزء Brain الذي تسأله أسئلة بلغة عادية فيجيب من مستنداتك ومهامك، مثل: «ما آخر قرار في مشروع الألياف؟». بدلاً من البحث في عشرات الصفحات، تحصل على الجواب مع روابط المصادر.', 'The Knowledge Manager is the part of Brain you ask plain questions, and it answers from your Docs and tasks, like “What was the last decision on the fibre project?”. Instead of searching dozens of pages, you get the answer with links to the sources.'],
    [['افتح Brain واكتب سؤالك.', 'Open Brain and type your question.'], ['اقرأ الجواب وافتح روابط المصادر للتأكد.', 'Read the answer and open the source links to check.'], ['اطلب متابعة مثل «لخصها في ثلاث نقاط».', 'Ask a follow-up such as “summarise it in three points”.']],
    ['جودة الإجابات تعتمد على جودة مستنداتك؛ مستندات مرتبة = أجوبة أفضل.', 'Answer quality depends on your Docs; tidy Docs mean better answers.'], '#/workshops/ai'],
  ['ai', 'pm', ['مدير المشاريع بالذكاء الاصطناعي', 'ClickUp AI Project Manager'],
    ['مدير المشاريع (Project Manager) في Brain يكتب عنك تقارير التقدم، وملخص الاجتماع اليومي (Standup)، وتحديثات الفريق، اعتماداً على ما حدث فعلاً في المهام. يوفر عليك ساعة كل أسبوع في كتابة التقارير.', 'The Project Manager in Brain writes progress reports, daily standups and team updates for you, based on what actually happened in the tasks. It saves you an hour a week of report writing.'],
    [['اطلب من Brain «اكتب تحديث تقدم لهذه القائمة هذا الأسبوع».', 'Ask Brain to “write a progress update for this List this week”.'], ['راجع الأرقام والأسماء.', 'Check the numbers and names.'], ['انسخ التحديث إلى تعليق أو قناة الفريق.', 'Copy the update into a comment or the team channel.']],
    ['الذكاء الاصطناعي يكتب، وأنت المسؤول عن صحة ما يُرسل. راجع قبل النشر دائماً.', 'AI writes, but you are responsible for what is sent. Always review before you post.'], '#/workshops/ai'],
  ['ai', 'sop', ['إنشاء مسودة إجراء عمل (SOP) بالذكاء الاصطناعي', 'Drafting an SOP with ClickUp AI'],
    ['إجراء العمل القياسي (SOP) يشرح كيف يُنجز عمل متكرر خطوة بخطوة. داخل مستند اطلب من الذكاء الاصطناعي مسودة، مثل «إجراء استقبال طلب صيانة»، ثم عدّلها لتطابق طريقة فريقك الحقيقية.', 'A standard operating procedure (SOP) explains how a repeated job is done, step by step. Inside a Doc, ask the AI for a draft, like “procedure for receiving a maintenance request”, then edit it to match how your team really works.'],
    [['أنشئ Doc جديداً.', 'Create a new Doc.'], ['اكتب / أو اضغط زر AI واطلب مسودة SOP.', 'Type / or click the AI button and ask for an SOP draft.'], ['عدّل الخطوات وأضف أسماء المسؤولين الحقيقية.', 'Edit the steps and add the real owners.']],
    ['المسودة نقطة بداية وليست إجراءً معتمداً. اعتمدها مع مالك العملية قبل نشرها.', 'The draft is a starting point, not an approved procedure. Get the process owner to approve it before publishing.'], '#/workshops/ai'],
  ['ai', 'superagent', ['إنشاء وكيل ذكي (Super Agent)', 'Creating an AI Super Agent'],
    ['الوكيل الذكي (Super Agent) زميل ذكاء اصطناعي تعطيه مهمة محددة، مثل «استقبل الطلبات الجديدة ورتبها وأسندها». يمكنك الإشارة إليه أو إسناد مهام له، ويعمل بالصلاحيات التي تحددها. تنشئه من قسم AI بوصف ما تريده بكلماتك، ويطرح عليك المنشئ أسئلة ليضبطه. يتوفر حسب الخطة وإعدادات المسؤول.', 'A Super Agent is an AI teammate you give a specific job, like “take in new requests, sort them and assign them”. You can mention it or assign tasks to it, and it works within the permissions you set. You create it from the AI area by describing what you want in your own words, and the builder asks you questions to fine-tune it. Availability depends on your plan and admin settings.'],
    [['من شريط التنقل العام افتح AI واختر Create Agent.', 'From the global navigation open AI and choose Create Agent.'], ['صف وظيفة الوكيل بوضوح وأجب عن أسئلة المنشئ.', 'Describe the agent’s job clearly and answer the builder’s questions.'], ['جرّبه على مهام تجريبية قبل استخدامه مع العمل الحقيقي.', 'Test it on practice tasks before using it on real work.']],
    ['أعطِ الوكيل أقل صلاحيات تكفي لعمله، كما تفعل مع أي زميل جديد.', 'Give the agent the least access it needs, just as you would a new colleague.'], '#/workshops/ai'],
  ['ai', 'superagent-edit', ['تعديل الوكيل الذكي', 'Editing a Super Agent'],
    ['بعد إنشاء الوكيل ستكتشف أشياء تحتاج تحسيناً: تعليمات أوضح، أدوات إضافية، أو حدود أدق. افتح إعداداته من مركز الذكاء الاصطناعي (AI Hub) وعدّل تعليماته ومعرفته وصلاحياته، ثم جرّبه من جديد.', 'After creating an agent you will find things to improve: clearer instructions, extra tools or tighter limits. Open its settings from the AI Hub and edit its instructions, knowledge and permissions, then test it again.'],
    [['افتح AI Hub ثم قائمة الوكلاء.', 'Open the AI Hub, then the agents list.'], ['عدّل التعليمات بأمثلة واضحة لما تريد وما لا تريد.', 'Edit the instructions with clear examples of what you want and do not want.'], ['راجع ما قام به الوكيل مؤخراً قبل توسيع استخدامه.', 'Review what the agent did recently before expanding its use.']],
    ['التعليمات الجيدة قصيرة ومحددة: «افعل كذا، ولا تفعل كذا، وإن لم تتأكد فاسأل».', 'Good instructions are short and specific: “do this, never do that, and ask if unsure”.'], '#/workshops/ai'],
  ['ai', 'ai-ui', ['جولة في بقية واجهة الذكاء الاصطناعي', 'Exploring the rest of the AI interface'],
    ['الذكاء الاصطناعي موجود في أماكن كثيرة: في المهمة لتلخيصها أو اقتراح مهام فرعية، في المستند للكتابة وإعادة الصياغة والترجمة، في التعليقات لصياغة الرد، وفي البحث الشامل لسؤال أي شيء. جرّب زر AI أينما رأيته.', 'AI lives in many places: in a task to summarise it or suggest subtasks, in a Doc to write, rewrite and translate, in comments to draft a reply, and in enterprise search to ask anything. Try the AI button wherever you see it.'],
    [['في مهمة طويلة اطلب ملخصاً.', 'In a long task ask for a summary.'], ['في Doc حدد نصاً واطلب «اجعله أبسط».', 'In a Doc select text and ask “make it simpler”.'], ['جرّب الترجمة من العربية إلى الإنجليزية.', 'Try translating from Arabic to English.']],
    ['كلما كان طلبك أوضح (من، ماذا، بأي شكل) كانت النتيجة أفضل.', 'The clearer your request (who, what, in which format), the better the result.'], '#/workshops/ai'],
  ['ai', 'notetaker', ['مدوّن الاجتماعات الذكي (AI Notetaker)', 'The AI Notetaker'],
    ['مدوّن الاجتماعات يمكنه حضور اجتماعك ونسخ الحديث وتلخيصه واستخراج المهام المطلوبة، فتنتهي من الاجتماع ومحضره جاهز. يعتمد على الخطة وإعدادات الشركة، وأبلغ الحضور دائماً قبل التسجيل.', 'The AI Notetaker can join your meeting, transcribe it, summarise it and pull out the action items, so the minutes are ready when the meeting ends. It depends on your plan and company settings, and you should always tell attendees before recording.'],
    [['فعّله واربطه بتقويمك إن كان متاحاً.', 'Turn it on and connect your calendar if available.'], ['بعد الاجتماع راجع الملخص والمهام المقترحة.', 'After the meeting review the summary and suggested tasks.'], ['حوّل المهام المتفق عليها إلى مهام مسندة بمواعيد.', 'Turn the agreed items into assigned tasks with dates.']],
    ['لا تسجّل اجتماعات فيها معلومات حساسة إلا إن سمحت سياسة الشركة بذلك.', 'Do not record meetings with sensitive information unless company policy allows it.'], '#/workshops/ai'],

  /* ---------------- 5. Communication ---------------- */
  ['talk', 'comments', ['التواصل عبر التعليقات', 'Communication via comments'],
    ['التعليق داخل المهمة يبقي النقاش بجانب العمل نفسه، بدلاً من رسائل بريد متناثرة. اكتب @ ثم اسم الزميل ليصله إشعار، ويمكنك إسناد التعليق ليصبح بنداً يجب إنهاؤه.', 'A comment inside the task keeps the discussion right next to the work, instead of scattered emails. Type @ and a colleague’s name to notify them, and you can assign a comment so it becomes an item to resolve.'],
    [['افتح المهمة واكتب في خانة التعليق.', 'Open the task and type in the comment box.'], ['أشر إلى زميل بـ @.', 'Mention a colleague with @.'], ['أسند التعليق إن كان طلباً يجب تنفيذه.', 'Assign the comment if it is a request to act on.']],
    ['السؤال في تعليق المهمة يجيب عنه الجميع مرة واحدة، والسجل يبقى لمن ينضم لاحقاً.', 'A question in a task comment is answered once for everyone, and the record stays for whoever joins later.'], 'l6-1'],
  ['talk', 'chat', ['المحادثات (Chat)', 'Chat functionality'],
    ['Chat في ClickUp مثل تطبيق محادثة داخل مكان العمل: رسائل مباشرة وقنوات للفريق. الفرق أن الرسالة يمكن أن تتحول إلى مهمة بنقرة، فلا يضيع طلب في زحمة المحادثة.', 'ClickUp Chat is like a messaging app inside your workplace: direct messages and team channels. The difference is that a message can become a task with one click, so no request gets lost in the chatter.'],
    [['افتح Chat من شريط التنقل.', 'Open Chat from the navigation bar.'], ['أرسل رسالة مباشرة لزميل.', 'Send a direct message to a colleague.'], ['حوّل رسالة فيها طلب إلى مهمة.', 'Turn a message containing a request into a task.']],
    ['المحادثة للسرعة، والمهمة للالتزام. أي شيء له موعد ومسؤول يجب أن يصبح مهمة.', 'Chat is for speed, tasks are for commitment. Anything with a deadline and an owner should become a task.'], 'l6-2'],
  ['talk', 'channels', ['قنوات ClickUp', 'ClickUp Channels'],
    ['القناة مكان محادثة دائم لموضوع أو فريق أو مشروع، ويمكن ربطها بالمساحة أو القائمة. كل من يعمل في المشروع يجد التحديثات في مكان واحد.', 'A Channel is a lasting conversation space for a topic, team or project, and it can be linked to a Space or List. Everyone on the project finds updates in one place.'],
    [['أنشئ قناة باسم المشروع.', 'Create a Channel named after the project.'], ['أضف أعضاء الفريق.', 'Add the team members.'], ['ثبّت الرسائل المهمة مثل رابط الخطة.', 'Pin important messages such as the plan link.']],
    ['قناة واحدة لكل مشروع أفضل من مجموعات كثيرة متداخلة.', 'One channel per project beats many overlapping groups.'], 'l6-2'],
  ['talk', 'teams', ['فرق ClickUp (Teams)', 'ClickUp Teams'],
    ['الفريق (Team) في ClickUp مجموعة أشخاص مسماة، مثل «فريق الشبكات». تستطيع إسناد المهام أو مشاركة الأماكن مع الفريق كله دفعة واحدة، والإشارة إليه بـ @ في التعليقات.', 'A Team in ClickUp is a named group of people, like “Network team”. You can assign tasks or share locations with the whole team at once, and @mention it in comments.'],
    [['من إعدادات الأشخاص أو الفرق أنشئ فريقاً (قد يحتاج صلاحية).', 'From People or Teams settings create a Team (may need permission).'], ['أضف الأعضاء.', 'Add the members.'], ['جرب @اسم_الفريق في تعليق.', 'Try @TeamName in a comment.']],
    ['عند انضمام موظف جديد أضفه للفريق، فيحصل تلقائياً على ما شُورك مع الفريق.', 'When a new employee joins, add them to the Team and they get everything shared with it.'], 'l11-1'],

  /* ---------------- 6. Dashboards ---------------- */
  ['dash', 'dash-intro', ['مقدمة إلى لوحات المعلومات', 'Intro to ClickUp Dashboards'],
    ['لوحة المعلومات (Dashboard) شاشة واحدة تجيب عن «كيف يسير العمل؟» ببطاقات: عدد المهام المتأخرة، مخطط الحالات، عبء العمل، والوقت المسجل. مديرك لن يحتاج أن يسألك؛ اللوحة تجيبه.', 'A Dashboard is one screen that answers “how is the work going?” with cards: overdue count, a status chart, workload and tracked time. Your manager will not need to ask you; the dashboard answers.'],
    [['افتح Dashboards من الشريط الجانبي.', 'Open Dashboards from the sidebar.'], ['أنشئ لوحة جديدة.', 'Create a new dashboard.'], ['أضف بطاقة واحدة واختر مصدر بياناتها.', 'Add one card and choose its data source.']],
    ['ابدأ بثلاث بطاقات فقط تجيب عن أهم ثلاثة أسئلة لديك.', 'Start with only three cards that answer your three most important questions.'], 'l8-1'],
  ['dash', 'dash-template', ['إنشاء لوحة من قالب', 'Creating a dashboard from a template'],
    ['لا داعي للبدء من الصفر. ClickUp يقدم قوالب لوحات جاهزة لإدارة المشاريع أو الفرق أو المبيعات. اختر قالباً، اربطه بقائمتك أو مساحتك، وستمتلئ البطاقات ببياناتك.', 'No need to start from scratch. ClickUp offers ready dashboard templates for project, team or sales management. Pick one, connect it to your List or Space, and the cards fill with your data.'],
    [['عند إنشاء لوحة اختر من القوالب.', 'When creating a dashboard choose from templates.'], ['حدد المساحة أو القائمة مصدراً للبيانات.', 'Select the Space or List as the data source.'], ['احذف البطاقات التي لا تحتاجها.', 'Delete the cards you do not need.']],
    ['القالب بداية؛ عدّل عناوين البطاقات لتناسب لغة فريقك.', 'A template is a start; rename the cards to suit your team’s language.'], '#/studio'],
  ['dash', 'dash-more', ['وظائف إضافية في لوحات المعلومات', 'Additional dashboard functionality'],
    ['للوحات مزايا تجعلها أقوى: فلاتر على مستوى اللوحة، بطاقات حسابية (مجموع، متوسط)، تتبع الوقت، الأهداف، ومشاركة اللوحة أو جدولة إرسالها. وتستطيع النقر على أي رقم لترى المهام خلفه.', 'Dashboards have features that make them stronger: dashboard-wide filters, calculation cards (sum, average), time tracking, goals, and sharing or scheduling the dashboard. You can click any number to see the tasks behind it.'],
    [['أضف فلتر اللوحة حسب الفترة أو المسؤول.', 'Add a dashboard filter by period or assignee.'], ['أضف بطاقة Calculation لمجموع حقل مالي.', 'Add a Calculation card to total a money field.'], ['شارك اللوحة مع مديرك.', 'Share the dashboard with your manager.']],
    ['قبل استنتاج أي شيء من رقم، انقر عليه وتأكد من المهام التي يحسبها.', 'Before drawing a conclusion from a number, click it and check which tasks it counts.'], 'l8-2'],

  /* ---------------- 7. Import and export ---------------- */
  ['data', 'export', ['تصدير البيانات من ClickUp', 'Exporting data from ClickUp'],
    ['أحياناً تحتاج البيانات خارج ClickUp، مثلاً لتقرير في Excel. يمكنك تصدير العرض الحالي إلى CSV أو Excel، ويُصدَّر ما تراه بفلاتره وأعمدته.', 'Sometimes you need data outside ClickUp, for example for an Excel report. You can export the current view to CSV or Excel, and what you see is exported with its filters and columns.'],
    [['رتب العرض بالأعمدة والفلاتر المطلوبة.', 'Set up the view with the columns and filters you need.'], ['افتح قائمة النقاط أو Export واختر الصيغة.', 'Open the ellipsis menu or Export and choose a format.'], ['افتح الملف وتأكد من البيانات.', 'Open the file and check the data.']],
    ['انتبه لما تصدره: الملف يخرج من حماية صلاحيات ClickUp، فلا ترسله لمن لا يحق له.', 'Be careful what you export: the file leaves ClickUp’s permissions, so do not send it to anyone not entitled to it.'], '#/workshops/import'],
  ['data', 'import', ['استيراد البيانات إلى ClickUp', 'Importing data to ClickUp'],
    ['لديك ملف Excel فيه المهام؟ لا تنسخها يدوياً. جهّز الملف بصف عناوين وعمود لكل حقل، ثم استورده وطابق الأعمدة مع حقول ClickUp. ويوجد أيضاً استيراد جاهز من أدوات مثل Trello وAsana وJira.', 'Have an Excel file of tasks? Do not copy it by hand. Prepare the file with a header row and one column per field, then import it and match columns to ClickUp fields. There are also ready importers for tools like Trello, Asana and Jira.'],
    [['جهز الملف: عناوين واضحة وتواريخ بصيغة واحدة.', 'Prepare the file: clear headers and dates in one format.'], ['من الإعدادات افتح Import/Export واختر CSV أو Excel.', 'In settings open Import/Export and choose CSV or Excel.'], ['طابق الأعمدة وراجع المعاينة قبل التأكيد.', 'Map the columns and review the preview before confirming.']],
    ['جرّب الاستيراد أولاً على قائمة تجريبية بعشرة صفوف.', 'Test the import first on a practice List with ten rows.'], '#/workshops/import'],

  /* ---------------- 8. Templates ---------------- */
  ['tpl', 'tpl-intro', ['مقدمة إلى القوالب', 'Intro to ClickUp templates'],
    ['القالب نسخة جاهزة من عمل متكرر: قائمة مشروع بمراحلها، مهمة بقائمة تحقق، أو مستند بشكل ثابت. بدلاً من بناء نفس الشيء كل مرة، تستخدم القالب وتبدأ فوراً.', 'A template is a ready copy of repeated work: a project List with its stages, a task with a checklist, or a Doc with a fixed layout. Instead of building the same thing every time, you use the template and start right away.'],
    [['افتح Template Center من زر «+».', 'Open the Template Center from the “+” button.'], ['تصفح قوالب حسب القسم.', 'Browse templates by department.'], ['افتح معاينة قالب لترى ما يحتويه.', 'Open a template preview to see what it contains.']],
    ['أي عمل تكرره أكثر من ثلاث مرات يستحق قالباً.', 'Any work you repeat more than three times deserves a template.'], '#/workshops/templates'],
  ['tpl', 'tpl-use', ['كيف تستخدم القوالب', 'How to use templates'],
    ['لاستخدام قالب: اختره من مركز القوالب، حدد أين يوضع (مساحة، مجلد، قائمة)، واختر ما يُنسخ مثل المهام والتواريخ والمسؤولين. خلال ثوانٍ يصبح المشروع جاهزاً.', 'To use a template: pick it from the Template Center, choose where it goes (Space, Folder, List), and choose what to copy such as tasks, dates and assignees. In seconds the project is ready.'],
    [['اختر القالب واضغط Use template.', 'Choose the template and click Use template.'], ['حدد الموقع واسم المشروع الجديد.', 'Set the location and the new project name.'], ['اختر تعديل التواريخ لتبدأ من اليوم.', 'Choose to shift dates so they start from today.']],
    ['بعد الاستخدام راجع المسؤولين؛ القالب قد يحمل أسماء من مشروع سابق.', 'After using it, check the assignees; a template may carry names from an old project.'], '#/workshops/templates'],
  ['tpl', 'tpl-save', ['حفظ قوالبك الخاصة', 'Saving your own templates'],
    ['أفضل القوالب هي التي تصنعها من عملك الحقيقي. عندما تنجح قائمة أو مهمة، احفظها كقالب لتعيد استخدامها أنت وفريقك، وحدّثها كلما تحسنت طريقتكم.', 'The best templates are the ones you make from your real work. When a List or task works well, save it as a template so you and your team can reuse it, and update it as your way of working improves.'],
    [['من قائمة النقاط للقائمة أو المهمة اختر Save as template.', 'From the List’s or task’s ellipsis menu choose Save as template.'], ['سمِّه بوضوح واختر ما يُحفظ.', 'Name it clearly and choose what to keep.'], ['شاركه مع الفريق.', 'Share it with the team.']],
    ['أضف وصفاً قصيراً للقالب: متى يُستخدم ولمن.', 'Add a short description to the template: when to use it and for whom.'], '#/workshops/templates'],

  /* ---------------- 9. Everyday pro tips ---------------- */
  ['pro', 'mute', ['كتم الإشعارات', 'Muting notifications'],
    ['الإشعارات الكثيرة تشتت التركيز. اضبطها لتصلك المهمة فقط: الإشارات إليك والمهام المسندة لك. ويمكنك إيقاف متابعة مهمة معينة إذا لم تعد تعنيك.', 'Too many notifications break your focus. Tune them so only what matters reaches you: mentions and tasks assigned to you. You can also stop watching a specific task that no longer concerns you.'],
    [['من صورتك افتح Settings ثم Notifications.', 'From your avatar open Settings, then Notifications.'], ['أوقف إشعارات البريد غير الضرورية.', 'Turn off unnecessary email notifications.'], ['في مهمة لا تعنيك أزل نفسك من المتابعين.', 'On a task that does not concern you, remove yourself as a watcher.']],
    ['خصص وقتين في اليوم لمراجعة صندوق الوارد بدلاً من مطاردة كل إشعار.', 'Set two times a day to review the Inbox instead of chasing every notification.'], 'l1-3'],
  ['pro', '2fa', ['حماية حسابك بالتحقق بخطوتين', 'Securing your account with 2FA'],
    ['التحقق بخطوتين يعني أن كلمة المرور وحدها لا تكفي للدخول؛ يلزم أيضاً رمز من تطبيق المصادقة أو رسالة. حتى لو سُرقت كلمة المرور يبقى حسابك محمياً.', 'Two-factor authentication means a password alone is not enough to sign in; a code from an authenticator app or a text message is also needed. Even if your password is stolen, your account stays protected.'],
    [['افتح Settings ثم Security.', 'Open Settings, then Security.'], ['اختر تطبيق المصادقة وامسح الرمز.', 'Choose the authenticator app and scan the code.'], ['احفظ رموز الاسترداد في مكان آمن.', 'Keep the recovery codes somewhere safe.']],
    ['إن كانت شركتك تستخدم الدخول الموحّد (SSO)، فأمان الدخول تديره الشركة.', 'If your company uses single sign-on (SSO), sign-in security is managed by the company.'], 'l11-1'],
  ['pro', 'shortcuts', ['اختصارات ClickUp', 'ClickUp shortcuts'],
    ['الاختصارات تجعلك أسرع بكثير. أشهرها Ctrl/Cmd+K للبحث. وبعد تفعيل الاختصارات من الإعدادات: T لمهمة جديدة، R لتذكير، M لإسناد المهمة لنفسك. قد تختلف حسب الإصدار.', 'Shortcuts make you much faster. The best known is Ctrl/Cmd+K to search. After turning shortcuts on in settings: T for a new task, R for a reminder, M to assign the task to yourself. They may vary by version.'],
    [['فعّل الاختصارات من Preferences.', 'Turn on shortcuts in Preferences.'], ['تعلّم اختصاراً واحداً كل يوم.', 'Learn one shortcut a day.'], ['اطبع قائمة الاختصارات وضعها بجانبك أسبوعاً.', 'Print the shortcut list and keep it next to you for a week.']],
    ['Ctrl/Cmd+K وحده يوفر عليك نصف التنقل في ClickUp.', 'Ctrl/Cmd+K alone saves you half of your clicking around.'], 'l12-1'],
  ['pro', 'themes', ['مظاهر ClickUp', 'ClickUp themes'],
    ['يمكنك تغيير مظهر ClickUp ليريح عينيك: الوضع الفاتح أو الداكن أو التلقائي حسب جهازك، ولون التمييز المفضل لديك. تفصيل صغير يجعل العمل اليومي أمتع.', 'You can change ClickUp’s look to rest your eyes: light, dark, or automatic to follow your device, plus your favourite accent colour. A small detail that makes daily work nicer.'],
    [['افتح Settings ثم Themes أو Preferences.', 'Open Settings, then Themes or Preferences.'], ['اختر الوضع الداكن أو التلقائي.', 'Choose dark or automatic mode.'], ['اختر لون التمييز.', 'Pick an accent colour.']],
    ['الوضع الداكن مريح في العمل الليلي، والتلقائي يغيّر نفسه مع الوقت.', 'Dark mode is easier at night, and automatic switches by itself.'], 'l1-2'],
  ['pro', 'restore', ['استعادة العناصر المحذوفة', 'Restoring deleted items'],
    ['حذفت شيئاً بالخطأ؟ لا تقلق. العناصر المحذوفة تذهب إلى سلة المهملات (Trash) لمدة 30 يوماً تقريباً، ويمكنك استعادتها. انتبه: التعليقات وسجلات الوقت المحذوفة لا تُستعاد.', 'Deleted something by mistake? Don’t worry. Deleted items go to Trash for about 30 days, and you can restore them. Careful: deleted comments and time entries cannot be restored.'],
    [['افتح Trash من الشريط الجانبي أو الإعدادات.', 'Open Trash from the sidebar or settings.'], ['ابحث عن العنصر.', 'Find the item.'], ['اضغط Restore.', 'Click Restore.']],
    ['بدلاً من حذف المشاريع المنتهية، أرشفها؛ تختفي من أمامك وتبقى متاحة دائماً.', 'Instead of deleting finished projects, archive them; they disappear from view but stay available forever.'], 'l2-1'],
  ['pro', 'time', ['تتبع الوقت', 'Time tracking'],
    ['تتبع الوقت يجيب عن «كم أخذ هذا العمل فعلاً؟». شغّل المؤقت عند البدء وأوقفه عند الانتهاء، أو أضف الوقت يدوياً. مع الوقت تصبح تقديراتك أدق وخططك واقعية.', 'Time tracking answers “how long did this work really take?”. Start the timer when you begin and stop it when you finish, or add time manually. Over time your estimates get sharper and your plans realistic.'],
    [['افتح المهمة واضغط Start على المؤقت.', 'Open the task and press Start on the timer.'], ['أوقفه عند الانتهاء.', 'Stop it when you finish.'], ['راجع أوقاتك في تقرير أو لوحة.', 'Review your times in a report or dashboard.']],
    ['قارن الوقت المقدر بالفعلي بعد كل مشروع؛ هكذا تتعلم التخطيط.', 'Compare estimated and actual time after each project; that is how you learn to plan.'], 'l7-1'],
  ['pro', 'notepad', ['المفكرة (Notepad)', 'The Notepad'],
    ['المفكرة دفتر ملاحظاتك الخاص داخل ClickUp: لا يراه أحد غيرك. اكتب فيها أفكاراً سريعة أو قائمة مهام اليوم، وحوّل أي ملاحظة إلى مهمة حقيقية عندما تصبح جاهزة.', 'The Notepad is your private notebook inside ClickUp: nobody else can see it. Jot quick ideas or today’s to-do list, and turn any note into a real task when it is ready.'],
    [['افتح Notepad من زر الإجراءات السريعة أو اختصاره.', 'Open the Notepad from the quick action button or its shortcut.'], ['اكتب ملاحظة أو قائمة تحقق.', 'Write a note or a checklist.'], ['حوّل الملاحظة إلى مهمة.', 'Convert the note into a task.']],
    ['المفكرة للأفكار الخام؛ عندما تصبح الفكرة عملاً بموعد، انقلها إلى مهمة.', 'The Notepad is for raw ideas; when an idea becomes work with a deadline, move it to a task.'], 'l3-1'],
  ['pro', 'mywork', ['ميزة «عملي» (My Work)', 'The My Work feature'],
    ['«عملي» (My Work) يجمع كل ما يخصك من كل المساحات: المهام المسندة لك والتذكيرات، مرتبة حسب: اليوم، المتأخر، القادم، وبلا موعد. هي أفضل صفحة لتبدأ يومك.', 'My Work gathers everything that is yours from every Space: tasks assigned to you and reminders, sorted into Today, Overdue, Next and Unscheduled. It is the best page to start your day.'],
    [['افتح Home أو My Tasks حيث تجد My Work.', 'Open Home or My Tasks, where you find My Work.'], ['ابدأ بالمتأخر ثم مهام اليوم.', 'Start with Overdue, then Today.'], ['جدول المهام بلا موعد.', 'Schedule the unscheduled tasks.']],
    ['خصص خمس دقائق كل صباح لمراجعة My Work؛ ستعرف يومك قبل أن يبدأ.', 'Spend five minutes every morning on My Work; you will know your day before it starts.'], 'l1-2'],
  ['pro', 'reminder', ['إنشاء تذكير سريع', 'Creating a quick reminder'],
    ['التذكير أخف من المهمة: لا يحتاج قائمة ولا حقولاً. «اتصل بالمورد الساعة 10» مثال مثالي. يظهر في My Work ويصلك تنبيه في وقته، ويمكنك إرسال تذكير لزميل أيضاً.', 'A reminder is lighter than a task: no List, no fields. “Call the vendor at 10” is a perfect example. It shows in My Work and alerts you on time, and you can send a reminder to a colleague too.'],
    [['اضغط Create ثم Reminder، أو الاختصار R.', 'Click Create, then Reminder, or press R.'], ['اكتب النص والوقت.', 'Type the text and the time.'], ['احفظ.', 'Save.']],
    ['إذا كان الشيء يحتاج مسؤولاً آخر ومتابعة، فاجعله مهمة لا تذكيراً.', 'If it needs another owner and follow-up, make it a task, not a reminder.'], 'l3-5'],
  ['pro', 'mysettings', ['إعداداتي (My Settings)', 'My Settings'],
    ['في «إعداداتي» تضبط ما يخصك أنت فقط: الاسم والصورة، المنطقة الزمنية، اللغة، شكل التاريخ، الإشعارات، الأمان، والتطبيقات المرتبطة. ضبطها مرة واحدة يجعل كل شيء يعمل كما تتوقع.', 'In My Settings you control what is yours alone: name and photo, time zone, language, date format, notifications, security and connected apps. Setting them once makes everything work the way you expect.'],
    [['من صورتك افتح Settings.', 'From your avatar open Settings.'], ['راجع المنطقة الزمنية وصيغة التاريخ.', 'Check the time zone and date format.'], ['راجع الإشعارات والأمان.', 'Review notifications and security.']],
    ['المنطقة الزمنية الخاطئة سبب شائع لظهور المواعيد في وقت غير صحيح.', 'A wrong time zone is a common reason due times look off.'], 'l1-2'],

  /* ---------------- 10. Running the Workspace ---------------- */
  ['admin', 'wssettings', ['إعدادات مساحة العمل', 'Workspace settings'],
    ['إعدادات مساحة العمل تخص الشركة كلها ويديرها المالك والمسؤولون: الأعضاء والأدوار، الميزات المفعلة (ClickApps)، الأمان، الاستيراد، والتكاملات. كموظف عادي يكفي أن تعرف أين هي ومن تسأل.', 'Workspace settings affect the whole company and are managed by the owner and admins: members and roles, enabled features (ClickApps), security, import and integrations. As a regular employee, it is enough to know where they are and whom to ask.'],
    [['من صورتك أو اسم مساحة العمل افتح Settings.', 'From your avatar or the Workspace name open Settings.'], ['تصفح People وClickApps.', 'Browse People and ClickApps.'], ['لأي تغيير اطلب من مسؤول مساحة العمل.', 'For any change ask your Workspace admin.']],
    ['التغيير في إعدادات مساحة العمل يؤثر على الجميع؛ لذلك يقتصر على المسؤولين.', 'A change in Workspace settings affects everyone; that is why it is limited to admins.'], 'l11-1'],
  ['admin', 'schedule', ['ضبط جدول عمل الشركة', 'Setting the company work schedule'],
    ['جدول العمل يحدد أيام وساعات الدوام والعطل الرسمية. عندها لا يجدول ClickUp بداية أو استحقاق المهام في أيام العطلة، ويحسب عبء العمل على الأيام الحقيقية. مثلاً: الأحد إلى الخميس، والجمعة والسبت عطلة.', 'The work schedule sets working days, hours and public holidays. ClickUp then avoids scheduling task start or due dates on days off and calculates workload on the real working days. For example: Sunday to Thursday, with Friday and Saturday off.'],
    [['يفتح المالك أو المسؤول إعدادات مساحة العمل ثم Work schedule.', 'The owner or an admin opens Workspace settings, then Work schedule.'], ['يحدد أيام وساعات العمل.', 'They set working days and hours.'], ['يضيف العطل الرسمية.', 'They add public holidays.']],
    ['إذا ظهرت مواعيد في عطلة نهاية الأسبوع، فتحقق من جدول العمل مع المسؤول.', 'If dates land on the weekend, check the work schedule with your admin.'], 'l7-2'],
  ['admin', 'security', ['أمان مساحة العمل والصلاحيات', 'Workspace security and permissions'],
    ['الأمان يعني أن كل شخص يرى ما يحتاجه فقط. الأدوار: المالك، المسؤول، العضو، العضو المحدود، والضيف. ومستويات المشاركة: مشاهدة، تعليق، تعديل، تحكم كامل. ويمكن جعل الأماكن خاصة، وفرض التحقق بخطوتين.', 'Security means each person sees only what they need. The roles are Owner, Admin, Member, Limited Member and Guest. Sharing levels are View, Comment, Edit and Full access. Locations can be made private, and two-factor authentication can be required.'],
    [['اجعل المساحة أو القائمة الحساسة خاصة.', 'Make the sensitive Space or List private.'], ['شارك بأقل صلاحية تكفي للعمل.', 'Share with the lowest permission that gets the job done.'], ['راجع قائمة من لديه وصول كل فترة.', 'Review who has access from time to time.']],
    ['قواعد البيانات الحساسة تحددها سياسة الشركة المعتمدة، وليس هذا الدرس؛ اسأل فريق أمن المعلومات.', 'Rules for sensitive data come from the approved company policy, not this lesson; ask the information security team.'], 'l11-2'],
  ['admin', 'appcenter', ['مركز التطبيقات (App Center)', 'The App Center'],
    ['مركز التطبيقات هو المكان الذي تربط فيه ClickUp بأدوات أخرى، مثل Microsoft Teams وOutlook وGoogle Drive وSlack وGitHub وZoom. الربط يجعل المعلومات تنتقل تلقائياً بدلاً من النسخ اليدوي.', 'The App Center is where you connect ClickUp to other tools, like Microsoft Teams, Outlook, Google Drive, Slack, GitHub and Zoom. Connecting them makes information flow automatically instead of copying by hand.'],
    [['افتح App Center من الإعدادات أو التنقل.', 'Open the App Center from settings or navigation.'], ['ابحث عن الأداة التي تستخدمها.', 'Search for the tool you use.'], ['اطلب موافقة تقنية المعلومات قبل التفعيل.', 'Get IT approval before connecting it.']],
    ['كل تكامل يفتح باباً للبيانات؛ فعّل فقط ما يحتاجه العمل فعلاً.', 'Every integration opens a door for data; connect only what the work really needs.'], 'l12-2'],

  /* ---------------- 11. Automations ---------------- */
  ['auto', 'auto-intro', ['مقدمة إلى الأتمتة', 'ClickUp automations intro'],
    ['الأتمتة تعني: «عندما يحدث كذا، افعل كذا تلقائياً». مثلاً: عندما تتغير الحالة إلى «مكتمل»، أبلغ المدير. تتكون من مُشغِّل (Trigger) وشرط اختياري (Condition) وإجراء (Action). وهي تريحك من الأعمال المتكررة المملة.', 'An automation means: “when this happens, do that automatically”. For example: when the status changes to Complete, notify the manager. It is made of a Trigger, an optional Condition and an Action. It frees you from boring repetitive work.'],
    [['في القائمة اضغط Automate أو أيقونة البرق.', 'In the List click Automate or the lightning icon.'], ['تصفح الأتمتة الجاهزة.', 'Browse the ready-made automations.'], ['فعّل واحدة بسيطة وجرّبها.', 'Turn on a simple one and test it.']],
    ['ابدأ بأتمتة واحدة توفر عليك وقتاً كل يوم، ثم أضف غيرها.', 'Start with one automation that saves you time every day, then add more.'], 'l9-1'],
  ['auto', 'auto-edit', ['تعديل الأتمتة', 'Editing automations'],
    ['الأتمتة الجيدة تحتاج ضبطاً. يمكنك تعديل المشغّل أو الشرط أو الإجراء، أو إيقافها مؤقتاً. وكل أتمتة لها سجل يوضح متى عملت وماذا فعلت، فتعرف إن كانت تعمل كما تريد.', 'A good automation needs tuning. You can edit the trigger, condition or action, or pause it. Every automation has a log showing when it ran and what it did, so you know whether it works as intended.'],
    [['افتح قائمة الأتمتة في القائمة.', 'Open the automations list in the List.'], ['اضغط على الأتمتة لتعديلها.', 'Click the automation to edit it.'], ['راجع السجل (Activity) بعد التعديل.', 'Check its activity log after editing.']],
    ['إذا توقفت أتمتة، تحقق: هل تغيرت الحالة أو الشخص الذي تعتمد عليه؟ هل انتهى حد التشغيل الشهري؟', 'If an automation stops, check: did the status or person it uses change? Has the monthly run limit been reached?'], 'l9-2'],
  ['auto', 'auto-deep', ['الأتمتة بعمق', 'Automations deep dive'],
    ['الأتمتة المتقدمة تجمع شروطاً وإجراءات متعددة: «عندما تُنشأ مهمة في قائمة الطلبات، وإذا كانت الأولوية عاجلة، فأسندها لمشرف المناوبة وأضف قائمة تحقق وغيّر الموعد إلى اليوم». هكذا تبني سير عمل كاملاً يعمل وحده.', 'Advanced automations combine several conditions and actions: “When a task is created in the Requests List, and if the priority is Urgent, assign it to the shift supervisor, add a checklist and set the due date to today”. That is how you build a whole workflow that runs by itself.'],
    [['أنشئ أتمتة جديدة واختر المشغّل.', 'Create a new automation and choose the trigger.'], ['أضف شرطاً يحدد المهام المقصودة فقط.', 'Add a condition so it targets only the right tasks.'], ['أضف أكثر من إجراء وجرّبها على مهمة تجريبية.', 'Add more than one action and test it on a practice task.']],
    ['احذر الحلقات: أتمتتان تغيّر كل منهما ما تراقبه الأخرى قد تعملان بلا توقف.', 'Watch out for loops: two automations that each change what the other watches can run forever.'], '#/automations'],
  ['auto', 'auto-other', ['ميزات أتمتة أخرى', 'Other automation features'],
    ['إلى جانب الأتمتة العادية: النماذج تنشئ المهام تلقائياً، المهام المتكررة تعيد نفسها، القوالب تجهز المشاريع، والتكاملات تنقل البيانات، والوكلاء الأذكياء ينفذون أعمالاً أوسع. اجمعها معاً لتحصل على فريق يعمل بسلاسة.', 'Besides regular automations: Forms create tasks automatically, recurring tasks repeat themselves, templates set up projects, integrations move data, and AI agents handle bigger jobs. Combine them to get a team that runs smoothly.'],
    [['ارسم سير عمل فريقك من الطلب إلى الإنجاز.', 'Draw your team’s workflow from request to done.'], ['حدد أي خطوة تكرر نفسها.', 'Spot which step repeats itself.'], ['اختر الأداة المناسبة لها: نموذج، تكرار، قالب، أتمتة أو وكيل.', 'Pick the right tool for it: form, recurrence, template, automation or agent.']],
    ['الأتمتة الأفضل هي الأبسط التي تحل المشكلة؛ لا تعقّد ما يمكن أن يكون بسيطاً.', 'The best automation is the simplest one that solves the problem; do not complicate what can be simple.'], '#/workshops']
];

/* Role play: a job interview for a project collaboration role. */
const COURSE_INTERVIEW = [
  [['كيف تنظم مشروعاً جديداً في ClickUp؟', 'How would you organise a new project in ClickUp?'],
   ['أبدأ بالهيكل: مساحة للفريق، مجلد للمشروع، وقائمة لكل مرحلة. أضبط الحالات، وأقسم العمل إلى مهام بمسؤول وموعد، وأستخدم المهام الفرعية للأجزاء التي يعمل عليها آخرون، وأحفظ عرضاً للخطة يراه الجميع.', 'I start with the structure: a Space for the team, a Folder for the project and a List per stage. I set the statuses, split the work into tasks with one owner and a date, use subtasks for parts others work on, and save a plan view everyone can see.']],
  [['كيف تعرف أن الفريق مضغوط أو أن المشروع متأخر؟', 'How do you know the team is overloaded or the project is late?'],
   ['أستخدم عرض عبء العمل لرؤية من لديه أكثر من طاقته، وغانت لرؤية الاعتماديات والمسار الحرج، ولوحة معلومات تعرض المتأخرات والحالات. ثم أعيد توزيع المهام بإجراء جماعي وأخبر الفريق بالتغيير.', 'I use the Workload view to see who is over capacity, Gantt to see dependencies and the critical path, and a dashboard showing overdue tasks and statuses. Then I rebalance with bulk actions and tell the team about the change.']],
  [['أعطني مثالاً على أتمتة وفّرت وقتاً.', 'Give an example of an automation that saved time.'],
   ['عندما يصل طلب عبر النموذج، تُنشأ مهمة، وإذا كانت الأولوية عاجلة تُسند لمشرف المناوبة مع قائمة تحقق. هذا ألغى الفرز اليدوي، وأراجع سجل الأتمتة أسبوعياً للتأكد من عملها.', 'When a request arrives through the form, a task is created, and if it is urgent it is assigned to the shift supervisor with a checklist. That removed manual sorting, and I check the automation log weekly to make sure it works.']],
  [['كيف تستخدم الذكاء الاصطناعي في ClickUp بمسؤولية؟', 'How do you use AI in ClickUp responsibly?'],
   ['أستخدمه للتلخيص وكتابة المسودات وتقارير التقدم، وأراجع كل ناتج قبل إرساله. لا أُدخل بيانات سرية أو بيانات عملاء إلا إن سمحت سياسة معتمدة، وأعطي الوكلاء أقل صلاحيات تكفي.', 'I use it for summaries, drafts and progress reports, and I review every output before sending it. I do not enter confidential or customer data unless an approved policy allows it, and I give agents the least access they need.']],
  [['كيف تحافظ على التواصل منظماً؟', 'How do you keep communication organised?'],
   ['النقاش الخاص بمهمة يكون في تعليقاتها مع الإشارة للأشخاص، والطلبات تُسند كتعليقات أو تتحول لمهام، والتحديثات العامة في قناة المشروع. هكذا يبقى السجل مرتبطاً بالعمل.', 'Task discussion goes in that task’s comments with mentions, requests are assigned comments or become tasks, and general updates go in the project channel. That keeps the record tied to the work.']]
];
